$pdo=Database::connection();$action=strtolower((string)($argv[1]??'status'));
function exists(PDO $p,string $t):bool{try{$p->query('SELECT 1 FROM `'.$t.'` LIMIT 1');return true;}catch(Throwable){return false;}}
function cols(PDO $p,string $t):array{static $c=[];return$c[$t]??=$p->query('SHOW COLUMNS FROM `'.$t.'`')->fetchAll(PDO::FETCH_COLUMN);}
function add(PDO $p,string $t,array $d):int{$d=array_intersect_key($d,array_flip(cols($p,$t)));$f=array_keys($d);$p->prepare('INSERT INTO `'.$t.'` (`'.implode('`,`',$f).'`) VALUES (:'.implode(',:',$f).')')->execute($d);return(int)$p->lastInsertId();}
function demo(PDO $p):array|false{$q=$p->prepare('SELECT * FROM tenants WHERE slug=:s');$q->execute(['s'=>SPORTS_DEMO_SLUG]);return$q->fetch();}
function role(PDO $p,string $s):int{$q=$p->prepare('SELECT id FROM roles WHERE slug=:s');$q->execute(['s'=>$s]);return(int)$q->fetchColumn();}
