 if(demo($pdo))throw new RuntimeException('A Arena ApPlanner demonstração já existe.');foreach(['sports_courts','sports_modalities','sports_reservations','behavior_profiles'] as $t)if(!exists($pdo,$t))throw new RuntimeException('Execute as migrações antes: tabela ausente '.$t);$plan=(int)$pdo->query('SELECT id FROM plans WHERE active=1 ORDER BY monthly_price DESC,id DESC LIMIT 1')->fetchColumn();if(!$plan)throw new RuntimeException('Cadastre um plano ativo.');$now=date('Y-m-d H:i:s');$password='Arena!'.random_int(100000,999999).'Aa';$customers=[];$appointmentCustomers=[];$pdo->beginTransaction();try{
