   for($v=$visits;$v>=1;$v--){$start=(new DateTimeImmutable('today'))->modify('-'.(10+$v*(14+$i%4*7)).' days')->setTime(18+($i%4),0);$total=$courtSpec[$courtIndex][4];add($pdo,'sports_reservations',['public_id'=>bin2hex(random_bytes(16)),'tenant_id'=>$tenant,'court_id'=>$courts[$courtIndex],'modality_id'=>$courtSpec[$courtIndex][1],'customer_id'=>$cid,'customer_name'=>$fn.' '.$last[$i%8],'customer_phone'=>'8197'.str_pad((string)($i+1),7,'0',STR_PAD_LEFT),'customer_email'=>'arena.cliente'.str_pad((string)($i+1),2,'0',STR_PAD_LEFT).'@applanner.local','starts_at'=>$start->format('Y-m-d H:i:s'),'ends_at'=>$start->modify('+60 minutes')->format('Y-m-d H:i:s'),'duration_minutes'=>60,'price_per_hour'=>$total,'total_amount'=>$total,'deposit_amount'=>round($total*.3,2),'status'=>'completed','payment_method'=>'pix','payment_status'=>'paid','manage_token_hash'=>hash('sha256',bin2hex(random_bytes(32))),'source'=>'public','confirmed_at'=>$start->modify('-2 days')->format('Y-m-d H:i:s'),'created_at'=>$start->modify('-3 days')->format('Y-m-d H:i:s'),'updated_at'=>$start->format('Y-m-d H:i:s')]);add($pdo,'appointments',['tenant_id'=>$tenant,'customer_id'=>$cid,'professional_id'=>$professionals[$courtIndex],'service_id'=>$services[$courtIndex],'service_price_snapshot'=>$total,'starts_at'=>$start->format('Y-m-d H:i:s'),'ends_at'=>$start->modify('+60 minutes')->format('Y-m-d H:i:s'),'status'=>'completed','source'=>'public','notes'=>'Locação esportiva realizada — base de inteligência.','created_by'=>$owner,'created_at'=>$start->modify('-3 days')->format('Y-m-d H:i:s'),'updated_at'=>$start->format('Y-m-d H:i:s')]);$revenue+=$total;$completed++;}
